vim.keymap.set('n', '<leader>tl', require('helper_functions.tabs').close_tabs_to_left, { desc = '[T]ab close tabs to the [L]eft' })
vim.keymap.set('n', '<leader>tr', require('helper_functions.tabs').close_tabs_to_right, { desc = '[T]ab close tabs to the [R]ight' })

vim.keymap.set("n", "<leader>pu", require("undotree").open, { desc = "[P]ersonal [U]ndotree" })
vim.keymap.set('n', '<leader>pc', ':lcd %:h<cr>', { desc = '[P]ersonal change directory to [C]current' })
vim.keymap.set('n', '<leader>pd', require('helper_functions.toggle').toggle_diff, { desc = '[P]ersonal [D]iff toggle' })
vim.keymap.set('n', '<leader>pf', require('helper_functions.table').format_table, { desc = '[P]ersonal format [T]able' })
vim.keymap.set('n', '<leader>ph', require('helper_functions.by_filetype.markdown').toggle_markdown_checkbox, { desc = '[P]ersonal c[H]eckbox toggle' })
vim.keymap.set('n', '<leader>pl', require('helper_functions.toggle').toggle_fold_method, { desc = '[P]ersonal toggle fo[L]d' })
vim.keymap.set('n', '<leader>pm', require('helper_functions.toggle').toggle_mouse, { desc = '[P]ersonal toggle [M]ouse' })
vim.keymap.set('n', '<leader>pob', '<cmd>tabnew ~/.config/personal/.bashrc<CR>', { desc = '[P]ersonal c[O]nfiguration [B]ashrc' })
vim.keymap.set('n', '<leader>pr', ':lcd ' .. require('helper_functions.git').get_repo_root() .. '<cr>', { desc = '[P]ersonal change directory to repo [R]oot' })
vim.keymap.set('n', '<leader>pt', require('helper_functions.toggle').toggle_tab_width, { desc = '[P]ersonal toggle [T]ab' })
vim.keymap.set('n', '<leader>pyf', require('helper_functions.clipboard').copy_filename, { desc = '[P]ersonal [Y]ank [F]ilename' })
vim.keymap.set('n', '<leader>pyg', require('helper_functions.clipboard').copy_relative_file, { desc = '[P]ersonal [Y]ank [G]it relative file path' })
vim.keymap.set('n', '<leader>pynf', require('helper_functions.clipboard').copy_filename_line, { desc = '[P]ersonal [Y]ank [F]ilename and line[N]umber' })
vim.keymap.set('n', '<leader>pyng', require('helper_functions.clipboard').copy_relative_file_line, { desc = '[P]ersonal [Y]ank [G]it relative [F]ile path and line[N]umber' })
vim.keymap.set('n', '<leader>pynu', require('helper_functions.clipboard').copy_full_file_line, { desc = '[P]ersonal [Y]ank f[U]ll file path and line[N]umber' })
vim.keymap.set('n', '<leader>pyu', require('helper_functions.clipboard').copy_full_file, { desc = '[P]ersonal [Y]ank f[U]ll file path' })
